def snapshot_started_modes(apps, schema_editor):
    Stage = apps.get_model("competitions", "Stage")
    Match = apps.get_model("competitions", "Match")
    for stage in Stage.objects.using(schema_editor.connection.alias).all().iterator():
        Match.objects.using(schema_editor.connection.alias).filter(
            round__draw__stage_id=stage.pk,
            started_at__isnull=False,
        ).update(applied_series_mode=stage.series_mode)


